import { defineStore } from 'pinia'

const useCounter = defineStore('counter', {
  state: () => ({ n: 0 }),
  actions: {
    inc() {
      this.n++
    },
  },
})

const a = useCounter()
const b = useCounter()
a.inc()
b.inc()
console.log(a.n, b.n)

import { defineStore } from 'pinia'

let calls = 0
const useStats = defineStore('stats', {
  state: () => ({ items: [1, 2, 3] }),
  getters: {
    sum: (state) => {
      calls++
      return state.items.reduce((t, x) => t + x, 0)
    },
  },
})

const s = useStats()
s.sum
s.sum
s.items.push(4)
s.sum
console.log(calls, s.sum)
